INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'f2662290-5434-5237-95ba-49b265d56c84', '210bced0-45c7-56da-88c0-f8b9d274bfa3',
  '[L.O.3] Cho hàm sau:

```cpp
int fun1(int arr[], int size, int key, int k)
{
    int s = 0, e = size - 1, mid = s + (e - s) / 2;
    int ans = -1;
    while (s <= e) {
        if (arr[mid] == key) {
            if (arr[mid - k] == arr[mid]) e = mid - 1;
            else if (arr[mid - (k - 1)] == arr[mid]) {
                ans = mid;
                break;
            }
        } else s = mid + 1;
        } else if (key < arr[mid]) e = mid - 1;
        else if (key > arr[mid]) s = mid + 1;
        mid = s + (e - s) / 2;
    }
    return ans;
}
```

Hãy cho biết kết quả xuất ra màn hình sau khi đoạn mã dưới đây được thực thi.

```cpp
