INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '61ccface-f68a-5096-9910-c78c7a3f8487', '210bced0-45c7-56da-88c0-f8b9d274bfa3',
  '[L.O.3.3] Trong các hiện thực hàm băm đồ hash `h(k, p, M)` với `k` là khóa và `M` là kích thước bộ nhớ, hiện thực nào tốt nhất để giải quyết đụng độ theo phương pháp đánh địa chỉ mở?

Lựa chọn:
- `h(k,p,M) = (a*k + b*p) % M`, với `a, b` là hai hằng nguyên tố
- `h(k,p,M) = h1(k,M) + p*h2(k,M)`, với `h1, h2` là hai hàm băm
- `h(k,p,M) = (h1(k,M) + p*h2(k,M)) % M`, với `h1, h2` là hai hàm băm
- `h(k,p,M) = rot(p,k,p) % M`, với `rot` là hàm xoay
- Tất cả các câu trên đều sai', 19
);

