INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'b8b0db45-f0f1-5a91-8980-df21ac32b818', '210bced0-45c7-56da-88c0-f8b9d274bfa3',
  '[L.O.3.3] Cho hàm chèn node vào cây tìm kiếm nhị phân, trả về gốc của cây.

```cpp
TreeNode *bstInsert(TreeNode *root, int val)
{
    if (root == nullptr) { return new TreeNode(val); }
    TreeNode *curr = root;
    TreeNode *prev = nullptr;
    while (curr != nullptr) {
        prev = curr;
        // Code
    }
    if (val < prev->val) { prev->left = new TreeNode(val); } else { prev->right = new TreeNode(val); }
    return root;
}
```

Không chấp nhận khoá trùng trên cây, điền vào Code để hoàn thành hàm trên.

Lựa chọn:
- if (val < curr->val) curr = curr->left; else curr = curr->right;
- if (val < curr->val) curr = curr->left; else if (val > curr->val) curr = curr->right; else break;
- if (val < curr->val) curr = curr->left; else if (val > curr->val) curr = curr->right;
- if (val < curr->val) curr = curr->left; else if (val > curr->val) curr = curr->right; else return root;
- Tất cả các đáp án trên đều sai', 32
);

