INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'ad7a5461-94f7-509a-9c0c-dbad2fc8293a', '210bced0-45c7-56da-88c0-f8b9d274bfa3',
  '[L.O.3] Cho hàm foo2 hiện thực một giải thuật tìm kiếm:

```c
int foo2(int arr[], int x, int n) {
    int step = sqrt(n);
    int prev = 0;
    // Code here
    while (arr[prev] < x) {
        prev++;
        if (prev == min(step, n)) return -1;
    }
    if (arr[prev] == x) return prev;
    return -1;
}
```

Phải điền vào vị trí (`// Code here`) đoạn mã nào:

Lựa chọn:
- while (arr[step-1] < x){prev = step; step += sqrt(n);}
- while (arr[min(step, n)-1] < x){prev = step; step += sqrt(n);}
- while (arr[min(step, n)-1] < x){step += sqrt(n);}
- Tất cả các đáp án trên đều sai', 39
);

