INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '1fbde22d-5b7c-5b57-866b-7ee1fa18599a', '210bced0-45c7-56da-88c0-f8b9d274bfa3',
  'Dữ liệu cho các câu hỏi tiếp theo:

Cho lớp Graph hiện thực dùng ma trận liền kề như sau:

```cpp
class Graph {
private:
    int nover; // số đỉnh trong đồ thị
    int **wm; // ma trận trọng số
    int minDistance(int dist[], bool sptSet[]) {
        int min = INT_MAX, min_index;
        for ( int v = 0; v < nover; v++)
            if ( sptSet[v] == false && dist[v] <= min )
                min = dist[v], min_index = v;
        return min_index;
    }
}
```

Hãy chọn lựa đoạn mã thích hợp trong các chỗ trống trong đoạn mã sau để hoàn thành phương thức hiện thực giải thuật Dijkstra:

```cpp
void dijkstra(int src) {
    int dist[nover];
    bool sptSet[nover];
    for ( int i = 0; i < nover; i++)
        dist[i] = INT_MAX, sptSet[i] = false;
    dist[src] = 0;
    for ( int count = 0; count < /*Code1*/; count++) {
        int u = minDistance(dist, sptSet);
        /*Code2*/ = true;
        for ( int v = 0; v < nover; v++)
            if ( !sptSet[v] && dist[u] != INT_MAX && /*Code3*/ )
                dist[v] = /*Code4*/;
    }
    //printSolution(dist);
}
```

Điền vào Code2.

Lựa chọn:
- `sptSet[u]`
- `sptSet[src]`
- `sptSet[count]`
- `sptSet[nover]`', 53
);

